// Bundles scripts/lightfall/lightfall.entry.js (+ the `ogl` WebGL library) into ONE minified script and writes it as a string to
// src/components/auth/lightfall.bundle.generated.ts, which the login screens load into a WebView.
//
//   npm run build:lightfall
//
// The generated file is committed, so a normal app build does not need esbuild or ogl: they are build-time tools only.
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const result = await build({
  entryPoints: [path.join(root, 'scripts/lightfall/lightfall.entry.js')],
  bundle: true,
  minify: true,
  format: 'iife',
  target: ['es2019'], // runs in old Android System WebViews and iOS WKWebView (no newer syntax)
  legalComments: 'none',
  write: false,
});

const code = result.outputFiles[0].text.replace(/<\/script/gi, '<\\/script'); // never end the page's <script> early
const out = path.join(root, 'src/components/auth/lightfall.bundle.generated.ts');
writeFileSync(
  out,
  `// GENERATED by scripts/build-lightfall.mjs (npm run build:lightfall) - do not edit by hand.
// Lightfall (React Bits) + ogl, bundled for the login screens' WebView. ${Math.round(code.length / 1024)} KB.
export const LIGHTFALL_BUNDLE = ${JSON.stringify(code)};
`,
);
console.log(`wrote ${path.relative(root, out)} (${Math.round(code.length / 1024)} KB)`);
